-- WYN-211: WYNOS Food opens to everyone; ordering is limited to Maha Sarakham.
--
-- Founder decisions (2026-10-04):
-- * "Wynos Food เปิดให้ทุกคนเห็น แต่สามารถใช้ได้แค่คนที่อยู่ จ มหาสารคาม";
-- * a customer counts as "in Maha Sarakham" when the delivery pin is inside
--   the province boundary (checked on the server when quoting and ordering);
-- * a store must be pinned inside Maha Sarakham before it can open for sale;
-- * customers outside the province only see an introduction page (web).
--
-- How it works:
-- * food_service_areas holds the boundary as a simplified polygon
--   (OpenStreetMap relation 1908786, (c) OpenStreetMap contributors, ODbL;
--   Douglas-Peucker 0.0005 degrees, about 50 m, 1584 points).
-- * internal.food_in_service_area(lat, lng): bounding box, then ray casting.
-- * public.food_service_area_check(lat, lng): the same answer for the web
--   app's introduction gate (signed-in users only, no data returned).
-- * internal.food_delivery_fee (used by food_quote_order and
--   food_create_order) now also requires the store pin and the delivery pin
--   to be inside an active service area. Developer accounts skip this so
--   they can keep testing from anywhere.
-- * Store readiness gains "service_area": publishing needs a store pin
--   inside Maha Sarakham.
-- * food_rollout_settings.public_enabled is switched on (Founder approval).

create table if not exists public.food_service_areas (
  code text primary key,
  name text not null,
  active boolean not null default true,
  min_lat double precision not null,
  max_lat double precision not null,
  min_lng double precision not null,
  max_lng double precision not null,
  lats double precision[] not null,
  lngs double precision[] not null,
  updated_at timestamptz not null default now(),
  constraint food_service_areas_shape check (
    cardinality(lats) >= 3 and cardinality(lats) = cardinality(lngs)
    and min_lat <= max_lat and min_lng <= max_lng
  )
);

alter table public.food_service_areas enable row level security;
revoke all on table public.food_service_areas from public, anon, authenticated;

insert into public.food_service_areas (code, name, active, min_lat, max_lat, min_lng, max_lng, lats, lngs)
