  name = excluded.name, active = excluded.active,
  min_lat = excluded.min_lat, max_lat = excluded.max_lat,
  min_lng = excluded.min_lng, max_lng = excluded.max_lng,
  lats = excluded.lats, lngs = excluded.lngs, updated_at = now();

-- Ray casting over one polygon ring.
create or replace function internal.food_point_in_polygon(
  p_lat double precision, p_lng double precision,
  p_lats double precision[], p_lngs double precision[]
)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_inside boolean := false;
  v_n integer := cardinality(p_lats);
  v_j integer := v_n;
begin
  for v_i in 1..v_n loop
    if ((p_lats[v_i] > p_lat) <> (p_lats[v_j] > p_lat))
       and p_lng < (p_lngs[v_j] - p_lngs[v_i]) * (p_lat - p_lats[v_i]) / (p_lats[v_j] - p_lats[v_i]) + p_lngs[v_i] then
      v_inside := not v_inside;
    end if;
    v_j := v_i;
  end loop;
  return v_inside;
end;
$$;

create or replace function internal.food_in_service_area(p_lat double precision, p_lng double precision)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_lat is not null and p_lng is not null and exists (
    select 1 from public.food_service_areas a
    where a.active
      and p_lat between a.min_lat and a.max_lat
      and p_lng between a.min_lng and a.max_lng
      and internal.food_point_in_polygon(p_lat, p_lng, a.lats, a.lngs)
  );
$$;

revoke all on function internal.food_point_in_polygon(double precision,double precision,double precision[],double precision[]) from public, anon, authenticated;
revoke all on function internal.food_in_service_area(double precision,double precision) from public, anon, authenticated;

create or replace function public.food_service_area_check(p_latitude double precision, p_longitude double precision)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select auth.uid()) is not null and internal.food_in_service_area(p_latitude, p_longitude);
$$;

revoke all on function public.food_service_area_check(double precision,double precision) from public, anon;
grant execute on function public.food_service_area_check(double precision,double precision) to authenticated;

-- Delivery fee for one store and one drop-off point (WYN-196), now limited
-- to the service area for everyone except developer accounts.
create or replace function internal.food_delivery_fee(
  p_store_id uuid,
  p_latitude double precision,
  p_longitude double precision
)
returns table(distance_km numeric, delivery_fee numeric)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_store public.food_stores%rowtype;
  v_distance numeric;
  v_developer boolean := exists (select 1 from public.developer_accounts d where d.user_id = (select auth.uid()));
begin
  select * into v_store from public.food_stores where id = p_store_id;
  if not found then
    raise exception 'store is not accepting orders';
  end if;
  if not v_developer and not internal.food_in_service_area(v_store.latitude, v_store.longitude) then
    raise exception 'store is outside the service area';
  end if;
  if v_store.latitude is null then
    return query select null::numeric, v_store.delivery_fee;
    return;
  end if;
  if p_latitude is null or p_longitude is null
     or p_latitude not between -90 and 90 or p_longitude not between -180 and 180 then
    raise exception 'delivery location required';
  end if;
  if not v_developer and not internal.food_in_service_area(p_latitude, p_longitude) then
    raise exception 'outside service area';
  end if;
  v_distance := internal.food_distance_km(v_store.latitude, v_store.longitude, p_latitude, p_longitude);
  if v_distance > v_store.delivery_radius_km then
    raise exception 'outside delivery area';
  end if;
  return query select
    v_distance,
    (v_store.delivery_fee
      + ceil(greatest(v_distance - v_store.delivery_base_km, 0) * v_store.delivery_fee_per_km))::numeric;
end;
$$;

revoke all on function internal.food_delivery_fee(uuid,double precision,double precision) from public, anon, authenticated;

-- Store readiness (merchant core completion) plus the service area.
create or replace function internal.food_store_readiness_missing(p_store_id uuid)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select array_remove(array[
    case when coalesce(char_length(trim(s.name)),0)=0 then 'name' end,
    case when coalesce(char_length(trim(s.phone)),0)=0 then 'phone' end,
    case when coalesce(char_length(trim(s.address)),0)=0 then 'address' end,
    case when coalesce(char_length(trim(s.business_hours)),0)=0 then 'business_hours' end,
    case when coalesce(char_length(trim(s.delivery_area)),0)=0 then 'delivery_area' end,
    case when not (
      (coalesce(char_length(trim(s.promptpay_name)),0)>0 and coalesce(char_length(trim(s.promptpay_id)),0)>0)
      or (coalesce(char_length(trim(s.bank_account_name)),0)>0 and coalesce(char_length(trim(s.bank_account_number)),0)>0)
      or coalesce(char_length(trim(s.payment_qr_path)),0)>0
    ) then 'payment' end,
    case when not exists (
      select 1 from public.food_menu_items m
      where m.store_id=s.id and m.is_available
    ) then 'menu' end,
    case when not internal.food_in_service_area(s.latitude, s.longitude) then 'service_area' end
  ], null)
  from public.food_stores s
  where s.id=p_store_id;
$$;

revoke all on function internal.food_store_readiness_missing(uuid) from public, anon, authenticated;

-- Founder: open WYNOS Food to everyone.
update public.food_rollout_settings set public_enabled = true where id = true;
